export function useTranslation(langCode) {
  const idx = L.indexOf(langCode) >= 0 ? L.indexOf(langCode) : 0;
  return (key, params) => {
    const arr = T[key];
    if (!arr) return key;
    let s = arr[idx] || arr[0];
    if (params) Object.entries(params).forEach(([k,v]) => { s = s.replace(`{${k}}`, v); });
    return s;
  };
}

export function validateTranslationCatalog() {
  return Object.entries(T)
    .filter(([, values]) => !Array.isArray(values) || values.length !== L.length || values.some(value => typeof value !== 'string' || !value.trim()))
    .map(([key]) => key);
}
